use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    if s.is_empty() {
        return Err("empty version string".to_string());
    }

    let mut chars = s.chars().peekable();

    // Parse major
    let major = parse_numeric_id(&mut chars)?;

    if chars.peek() != Some(&'.') {
        return Err("expected dot after major".to_string());
    }
    chars.next(); // consume dot

    // Parse minor
    let minor = parse_numeric_id(&mut chars)?;

    if chars.peek() != Some(&'.') {
        return Err("expected dot after minor".to_string());
    }
    chars.next(); // consume dot

    // Parse patch
    let patch = parse_numeric_id(&mut chars)?;

    // Parse optional prerelease
    let prerelease = if chars.peek() == Some(&'-') {
        chars.next(); // consume '-'
        Some(parse_prerelease(&mut chars)?)
    } else {
        None
    };

    // Parse optional build
    let build = if chars.peek() == Some(&'+') {
        chars.next(); // consume '+'
        Some(parse_build(&mut chars)?)
    } else {
        None
    };

    // Ensure we've consumed the entire string
    if chars.peek().is_some() {
        return Err("unexpected characters after version".to_string());
    }

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Parse a numeric identifier (0 or [1-9]\d*)
fn parse_numeric_id(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<u64, String> {
    let mut num_str = String::new();

    // First digit must be 0 or 1-9
    match chars.peek() {
        None => return Err("incomplete version string".to_string()),
        Some(&c) if !c.is_ascii_digit() => {
            return Err("expected digit".to_string());
        }
        Some(&'0') => {
            chars.next();
            num_str.push('0');
            // If it's a single '0', that's valid. If followed by more digits, it's invalid.
            if chars.peek().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                return Err("leading zeros not allowed".to_string());
            }
            return Ok(0);
        }
        Some(&c) if c.is_ascii_digit() => {
            num_str.push(c);
            chars.next();
        }
        _ => return Err("expected digit".to_string()),
    }

    // Subsequent digits
    while chars.peek().map(|c| c.is_ascii_digit()).unwrap_or(false) {
        num_str.push(chars.next().unwrap());
    }

    num_str
        .parse::<u64>()
        .map_err(|_| "number out of range".to_string())
}

/// Parse prerelease identifiers (separated by dots)
fn parse_prerelease(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<String, String> {
    let mut result = String::new();
    let mut first = true;

    loop {
        if !first {
            if chars.peek() == Some(&'.') {
                result.push('.');
                chars.next();
            } else {
                break;
            }
        }
        first = false;

        // Parse one prerelease identifier
        let id = parse_prerelease_id(chars)?;
        result.push_str(&id);

        // Stop if next char is not a dot and not part of prerelease
        match chars.peek() {
            Some(&'.') => continue,
            Some(&'+') | None => break,
            Some(&c) if c == '-' => break,
            _ => break,
        }
    }

    if result.is_empty() {
        return Err("empty prerelease".to_string());
    }

    Ok(result)
}

/// Parse a single prerelease identifier: 0 | [1-9]\d* | \d*[a-zA-Z-][0-9a-zA-Z-]*
fn parse_prerelease_id(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<String, String> {
    let mut id = String::new();

    // Collect all digits first
    while chars.peek().map(|c| c.is_ascii_digit()).unwrap_or(false) {
        id.push(chars.next().unwrap());
    }

    // If we have at least one character and it's all digits
    if !id.is_empty() && chars.peek().map(|c| !c.is_ascii_alphanumeric() && c != &'-').unwrap_or(true) {
        // Pure numeric identifier: must not have leading zeros (unless it's exactly "0")
        if id.len() > 1 && id.starts_with('0') {
            return Err("leading zeros not allowed in numeric prerelease identifier".to_string());
        }
        return Ok(id);
    }

    // Now collect letters and dashes
    let mut has_letter_or_dash = false;
    while let Some(&c) = chars.peek() {
        if c.is_ascii_alphanumeric() || c == '-' {
            has_letter_or_dash = true;
            id.push(c);
            chars.next();
        } else {
            break;
        }
    }

    if !has_letter_or_dash && id.is_empty() {
        return Err("empty prerelease identifier".to_string());
    }

    if !has_letter_or_dash && id.len() == 1 && id == "0" {
        return Ok(id);
    }

    if !has_letter_or_dash {
        // Pure numeric, already validated above
        if id.len() > 1 && id.starts_with('0') {
            return Err("leading zeros not allowed".to_string());
        }
    }

    if id.is_empty() {
        return Err("empty prerelease identifier".to_string());
    }

    Ok(id)
}

/// Parse build identifiers (separated by dots)
fn parse_build(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<String, String> {
    let mut result = String::new();
    let mut first = true;

    loop {
        if !first {
            if chars.peek() == Some(&'.') {
                result.push('.');
                chars.next();
            } else {
                break;
            }
        }
        first = false;

        // Parse one build identifier: [0-9a-zA-Z-]+
        let mut id = String::new();
        while let Some(&c) = chars.peek() {
            if c.is_ascii_alphanumeric() || c == '-' {
                id.push(c);
                chars.next();
            } else {
                break;
            }
        }

        if id.is_empty() {
            return Err("empty build identifier".to_string());
        }

        result.push_str(&id);

        // Stop if next char is not a dot
        if chars.peek() != Some(&'.') {
            break;
        }
    }

    if result.is_empty() {
        return Err("empty build".to_string());
    }

    Ok(result)
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut result = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(pre) = &v.prerelease {
        result.push('-');
        result.push_str(pre);
    }
    if let Some(build) = &v.build {
        result.push('+');
        result.push_str(build);
    }
    result
}

/// Compare prerelease versions using natural comparison.
/// 
/// Splits by dots and compares each part:
/// - numeric parts compare numerically
/// - numeric < alphanumeric
/// - alphanumeric parts compare lexically
/// - if all shared parts equal, more parts wins
fn nat_cmp(a: Option<&str>, b: Option<&str>) -> Ordering {
    let a_parts: Vec<&str> = a.map(|s| s.split('.').collect()).unwrap_or_default();
    let b_parts: Vec<&str> = b.map(|s| s.split('.').collect()).unwrap_or_default();

    for (sub_a, sub_b) in a_parts.iter().zip(b_parts.iter()) {
        let a_is_num = sub_a.chars().all(|c| c.is_ascii_digit());
        let b_is_num = sub_b.chars().all(|c| c.is_ascii_digit());

        let cmp = if a_is_num && b_is_num {
            // Both numeric: compare numerically
            let a_num: u64 = sub_a.parse().unwrap_or(0);
            let b_num: u64 = sub_b.parse().unwrap_or(0);
            a_num.cmp(&b_num)
        } else if a_is_num {
            // a is numeric, b is not: numeric is less
            Ordering::Less
        } else if b_is_num {
            // b is numeric, a is not: numeric is less (a is greater)
            Ordering::Greater
        } else {
            // Both alphanumeric: compare lexically
            sub_a.cmp(sub_b)
        };

        if cmp != Ordering::Equal {
            return cmp;
        }
    }

    // All shared identifiers are equal, more identifiers is greater
    a_parts.len().cmp(&b_parts.len())
}

/// Semver precedence.
///
/// Careful — this is where naive translations break:
///   * build metadata is IGNORED entirely for precedence
///   * a version WITH a prerelease is LOWER than the same version without
///   * prerelease identifiers compare left to right, dot-separated
///   * all-numeric identifiers compare numerically
///   * all other identifiers compare lexically in ASCII order
///   * numeric identifiers always rank LOWER than non-numeric ones
///   * if all preceding identifiers are equal, more identifiers wins
///
/// The spec's own worked example, which you should be able to reproduce:
///   1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta
///     < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Compare major, minor, patch
    match a.major.cmp(&b.major) {
        Ordering::Equal => {}
        other => return other,
    }
    match a.minor.cmp(&b.minor) {
        Ordering::Equal => {}
        other => return other,
    }
    match a.patch.cmp(&b.patch) {
        Ordering::Equal => {}
        other => return other,
    }

    // If all numeric parts are equal, compare prerelease
    // A version WITHOUT prerelease is GREATER than one WITH
    match (a.prerelease.as_deref(), b.prerelease.as_deref()) {
        (None, None) => Ordering::Equal,
        (None, Some(_)) => Ordering::Greater,
        (Some(_), None) => Ordering::Less,
        (Some(pre_a), Some(pre_b)) => nat_cmp(Some(pre_a), Some(pre_b)),
    }
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
///
/// Do not guess the prerelease interaction — read `reference/version.py`
/// and check against the oracle. `evaluate.py` compares you to the real
/// `semver` package on every bump of every valid version it generates.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

