use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    // Parse "major.minor.patch[-prerelease][+build]"

    // Find build first (+ is after everything)
    let (version_and_pre, build) = if let Some(plus_idx) = s.find('+') {
        let build_part = &s[plus_idx + 1..];
        if build_part.is_empty() {
            return Err("empty build metadata".to_string());
        }
        if !validate_build(build_part) {
            return Err("invalid build metadata".to_string());
        }
        (&s[..plus_idx], Some(build_part.to_string()))
    } else {
        (s, None)
    };

    // Find prerelease (- separates prerelease)
    let (version_part, prerelease) = if let Some(dash_idx) = version_and_pre.find('-') {
        let pre_part = &version_and_pre[dash_idx + 1..];
        if pre_part.is_empty() {
            return Err("empty prerelease".to_string());
        }
        if !validate_prerelease(pre_part) {
            return Err("invalid prerelease".to_string());
        }
        (&version_and_pre[..dash_idx], Some(pre_part.to_string()))
    } else {
        (version_and_pre, None)
    };

    // Parse major.minor.patch
    let parts: Vec<&str> = version_part.split('.').collect();
    if parts.len() != 3 {
        return Err("version requires exactly three parts".to_string());
    }

    let major = parse_number(parts[0])?;
    let minor = parse_number(parts[1])?;
    let patch = parse_number(parts[2])?;

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

fn parse_number(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("empty version number".to_string());
    }

    // Check for leading zero: "0" is OK, but "01", "001" etc are not
    if s.len() > 1 && s.starts_with('0') {
        return Err("leading zeros not allowed".to_string());
    }

    // Check all digits
    if !s.chars().all(|c| c.is_ascii_digit()) {
        return Err("non-digit in version number".to_string());
    }

    s.parse::<u64>()
        .map_err(|_| "version number out of range".to_string())
}

fn validate_prerelease(s: &str) -> bool {
    // prerelease is dot-separated identifiers
    // Each identifier must match: 0 or [1-9]\d* or \d*[a-zA-Z-][0-9a-zA-Z-]*
    if s.is_empty() {
        return false;
    }

    for id in s.split('.') {
        if !validate_prerelease_id(id) {
            return false;
        }
    }
    true
}

fn validate_prerelease_id(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    // Check all chars are [0-9a-zA-Z-]
    if !s.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
        return false;
    }

    // Check if all numeric: must be "0" or [1-9]\d*
    if s.chars().all(|c| c.is_ascii_digit()) {
        // No leading zeros except for "0" itself
        if s.len() > 1 && s.starts_with('0') {
            return false;
        }
        return true;
    }

    // Not all numeric, so must have at least one non-digit.
    // This matches the regex \d*[a-zA-Z-][0-9a-zA-Z-]*
    // which means: optional digits, then a letter/dash, then anything
    let has_letter_or_dash = s.chars().any(|c| c.is_ascii_alphabetic() || c == '-');
    if !has_letter_or_dash {
        return false;
    }

    // If starts with digit, check for leading zero in the numeric prefix
    // e.g., "01abc" is invalid
    let mut chars = s.chars().peekable();
    if let Some('0') = chars.peek() {
        let leading_char = chars.next();
        if let Some(next) = chars.peek() {
            if next.is_ascii_digit() {
                // We have "0" followed by another digit, which is a leading zero
                return false;
            }
        }
    }

    true
}

fn validate_build(s: &str) -> bool {
    // build is dot-separated identifiers of [0-9a-zA-Z-]+
    if s.is_empty() {
        return false;
    }

    for id in s.split('.') {
        if id.is_empty() {
            return false;
        }
        if !id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
            return false;
        }
    }
    true
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(ref pre) = v.prerelease {
        s.push('-');
        s.push_str(pre);
    }
    if let Some(ref build) = v.build {
        s.push('+');
        s.push_str(build);
    }
    s
}

/// Semver precedence.
///
/// Careful — this is where naive translations break:
///   * build metadata is IGNORED entirely for precedence
///   * a version WITH a prerelease is LOWER than the same version without
///   * prerelease identifiers compare left to right, dot-separated
///   * all-numeric identifiers compare numerically
///   * all other identifiers compare lexically in ASCII order
///   * numeric identifiers always rank LOWER than non-numeric ones
///   * if all preceding identifiers are equal, more identifiers wins
///
/// The spec's own worked example, which you should be able to reproduce:
///   1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta
///     < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Compare major, minor, patch first
    match a.major.cmp(&b.major) {
        Ordering::Equal => {},
        ord => return ord,
    }

    match a.minor.cmp(&b.minor) {
        Ordering::Equal => {},
        ord => return ord,
    }

    match a.patch.cmp(&b.patch) {
        Ordering::Equal => {},
        ord => return ord,
    }

    // Compare prerelease
    match (a.prerelease.as_deref(), b.prerelease.as_deref()) {
        (None, None) => Ordering::Equal,
        (None, Some(_)) => Ordering::Greater,  // No prerelease > with prerelease
        (Some(_), None) => Ordering::Less,
        (Some(pre_a), Some(pre_b)) => {
            nat_cmp(pre_a, pre_b)
        }
    }
}

fn nat_cmp(a: &str, b: &str) -> Ordering {
    let a_parts: Vec<Identifier> = a.split('.').filter_map(parse_identifier).collect();
    let b_parts: Vec<Identifier> = b.split('.').filter_map(parse_identifier).collect();

    for (sub_a, sub_b) in a_parts.iter().zip(b_parts.iter()) {
        match cmp_identifier(sub_a, sub_b) {
            Ordering::Equal => continue,
            ord => return ord,
        }
    }

    a_parts.len().cmp(&b_parts.len())
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Identifier {
    Numeric(u64),
    Alphanumeric(String),
}

fn parse_identifier(s: &str) -> Option<Identifier> {
    if s.is_empty() {
        return None;
    }

    if s.chars().all(|c| c.is_ascii_digit()) {
        s.parse::<u64>().ok().map(Identifier::Numeric)
    } else {
        Some(Identifier::Alphanumeric(s.to_string()))
    }
}

fn cmp_identifier(a: &Identifier, b: &Identifier) -> Ordering {
    match (a, b) {
        (Identifier::Numeric(n_a), Identifier::Numeric(n_b)) => n_a.cmp(n_b),
        (Identifier::Numeric(_), Identifier::Alphanumeric(_)) => Ordering::Less,
        (Identifier::Alphanumeric(_), Identifier::Numeric(_)) => Ordering::Greater,
        (Identifier::Alphanumeric(s_a), Identifier::Alphanumeric(s_b)) => s_a.cmp(s_b),
    }
}

