use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    if s.is_empty() {
        return Err(format!("{} is not valid SemVer string", s));
    }

    // Find the positions of '-' and '+' delimiters
    let dash_pos = s.find('-');
    let plus_pos = s.find('+');

    // Determine where the main version part ends
    let version_end = match (dash_pos, plus_pos) {
        (Some(d), Some(p)) => d.min(p),
        (Some(d), None) => d,
        (None, Some(p)) => p,
        (None, None) => s.len(),
    };

    // Extract and parse the three version numbers
    let version_part = &s[..version_end];
    let parts: Vec<&str> = version_part.split('.').collect();

    if parts.len() != 3 {
        return Err(format!("{} is not valid SemVer string", s));
    }

    let major = parse_number(parts[0])?;
    let minor = parse_number(parts[1])?;
    let patch = parse_number(parts[2])?;

    // Extract prerelease if present
    let prerelease = if let Some(dash_idx) = dash_pos {
        let start = dash_idx + 1;
        let end = if let Some(plus_idx) = plus_pos {
            if plus_idx > dash_idx {
                plus_idx
            } else {
                return Err(format!("{} is not valid SemVer string", s));
            }
        } else {
            s.len()
        };

        if start >= end {
            return Err(format!("{} is not valid SemVer string", s));
        }

        let prerelease_str = &s[start..end];
        validate_prerelease_identifiers(prerelease_str)?;
        Some(prerelease_str.to_string())
    } else {
        None
    };

    // Extract build if present
    let build = if let Some(plus_idx) = plus_pos {
        let build_str = &s[plus_idx + 1..];
        if build_str.is_empty() {
            return Err(format!("{} is not valid SemVer string", s));
        }
        validate_build_identifiers(build_str)?;
        Some(build_str.to_string())
    } else {
        None
    };

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Parse a number that doesn't have leading zeros
fn parse_number(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("empty number".to_string());
    }

    // Check for leading zeros (except "0" itself)
    if s.len() > 1 && s.starts_with('0') {
        return Err("leading zero not allowed".to_string());
    }

    s.parse::<u64>()
        .map_err(|_| "invalid number".to_string())
}

/// Validate prerelease identifiers (dot-separated)
/// Pattern: 0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*
fn validate_prerelease_identifiers(s: &str) -> Result<(), String> {
    for identifier in s.split('.') {
        validate_prerelease_identifier(identifier)?;
    }
    Ok(())
}

/// Validate a single prerelease identifier
fn validate_prerelease_identifier(s: &str) -> Result<(), String> {
    if s.is_empty() {
        return Err("empty identifier".to_string());
    }

    // Check if it's all digits
    if s.chars().all(|c| c.is_ascii_digit()) {
        // Must be "0" or have no leading zero
        if s.len() > 1 && s.starts_with('0') {
            return Err("leading zero in numeric identifier".to_string());
        }
        Ok(())
    } else {
        // Must contain only [0-9a-zA-Z-] and at least one non-digit
        if s.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
            Ok(())
        } else {
            Err("invalid character in prerelease identifier".to_string())
        }
    }
}

/// Validate build identifiers (dot-separated)
/// Pattern: [0-9a-zA-Z-]+
fn validate_build_identifiers(s: &str) -> Result<(), String> {
    for identifier in s.split('.') {
        if identifier.is_empty() {
            return Err("empty build identifier".to_string());
        }
        if !identifier.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
            return Err("invalid character in build identifier".to_string());
        }
    }
    Ok(())
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut result = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(prerelease) = &v.prerelease {
        result.push('-');
        result.push_str(prerelease);
    }
    if let Some(build) = &v.build {
        result.push('+');
        result.push_str(build);
    }
    result
}

/// Semver precedence.
///
/// Careful — this is where naive translations break:
///   * build metadata is IGNORED entirely for precedence
///   * a version WITH a prerelease is LOWER than the same version without
///   * prerelease identifiers compare left to right, dot-separated
///   * all-numeric identifiers compare numerically
///   * all other identifiers compare lexically in ASCII order
///   * numeric identifiers always rank LOWER than non-numeric ones
///   * if all preceding identifiers are equal, more identifiers wins
///
/// The spec's own worked example, which you should be able to reproduce:
///   1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta
///     < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Compare major, minor, patch
    match a.major.cmp(&b.major) {
        Ordering::Equal => {}
        other => return other,
    }
    match a.minor.cmp(&b.minor) {
        Ordering::Equal => {}
        other => return other,
    }
    match a.patch.cmp(&b.patch) {
        Ordering::Equal => {}
        other => return other,
    }

    // Compare prerelease (build is ignored)
    compare_prerelease(&a.prerelease, &b.prerelease)
}

/// Compare two prerelease versions (or None if not present)
fn compare_prerelease(a: &Option<String>, b: &Option<String>) -> Ordering {
    match (a, b) {
        (None, None) => Ordering::Equal,
        // Version without prerelease is greater
        (Some(_), None) => Ordering::Less,
        (None, Some(_)) => Ordering::Greater,
        (Some(a_str), Some(b_str)) => compare_prerelease_str(a_str, b_str),
    }
}

/// Compare two prerelease strings with natural comparison
fn compare_prerelease_str(a: &str, b: &str) -> Ordering {
    let a_parts: Vec<&str> = a.split('.').collect();
    let b_parts: Vec<&str> = b.split('.').collect();

    // Compare each part
    for (a_part, b_part) in a_parts.iter().zip(b_parts.iter()) {
        match (a_part.parse::<u64>(), b_part.parse::<u64>()) {
            // Both numeric: compare numerically
            (Ok(a_num), Ok(b_num)) => match a_num.cmp(&b_num) {
                Ordering::Equal => continue,
                other => return other,
            },
            // Numeric vs non-numeric: numeric is less
            (Ok(_), Err(_)) => return Ordering::Less,
            (Err(_), Ok(_)) => return Ordering::Greater,
            // Both non-numeric: compare lexically
            (Err(_), Err(_)) => match a_part.cmp(b_part) {
                Ordering::Equal => continue,
                other => return other,
            },
        }
    }

    // If all parts matched, more parts wins
    a_parts.len().cmp(&b_parts.len())
}

