/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    if s.is_empty() {
        return Err(format!("{} is not valid SemVer string", s));
    }

    // Find the + and - positions in the string
    let plus_pos = s.find('+');
    let minus_pos = s.find('-');

    // The - is a prerelease separator ONLY if it comes before the + (or there is no +)
    let prerelease_sep = match (minus_pos, plus_pos) {
        (Some(m), Some(p)) if m < p => Some(m),
        (Some(m), None) => Some(m),
        _ => None,
    };

    // Determine where the main version part ends
    let version_end = prerelease_sep.or(plus_pos).unwrap_or(s.len());

    // Extract and parse the three version numbers
    let version_part = &s[..version_end];
    let parts: Vec<&str> = version_part.split('.').collect();

    if parts.len() != 3 {
        return Err(format!("{} is not valid SemVer string", s));
    }

    let major = parse_number(parts[0])?;
    let minor = parse_number(parts[1])?;
    let patch = parse_number(parts[2])?;

    // Extract prerelease if present
    let prerelease = if let Some(sep_idx) = prerelease_sep {
        let start = sep_idx + 1;
        let end = plus_pos.unwrap_or(s.len());

        if start >= end {
            return Err(format!("{} is not valid SemVer string", s));
        }

        let prerelease_str = &s[start..end];
        validate_prerelease_identifiers(prerelease_str)?;
        Some(prerelease_str.to_string())
    } else {
        None
    };

    // Extract build if present
    let build = if let Some(sep_idx) = plus_pos {
        let build_str = &s[sep_idx + 1..];
        if build_str.is_empty() {
            return Err(format!("{} is not valid SemVer string", s));
        }
        validate_build_identifiers(build_str)?;
        Some(build_str.to_string())
    } else {
        None
    };

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}
